// Recurrence Lab -- vanilla JS, no build step.
// Loads content.json (hand-authored mechanism/citation text) and results.json
// (generated by experiment/aggregate.py) and renders the interactive grid.

const RESULTS_SYSTEM_MAP = {
  transformer: "transformer_qwen2.5-1.5b-instruct",
  huginn: "huginn-0125",
};

let CONTENT = null;
let RESULTS = { curves: [], per_problem: {} };

const $ = (sel) => document.querySelector(sel);

// ---------- floating tutorial walkthrough ----------

const TUTORIAL_SLIDES = [
  {
    title: "What is Recurrence Lab?",
    body: "More inference compute usually helps -- up to a point. This explorable shows exactly where that point is, and why it's different for every method-system pair. There is one claim: accuracy saturates, and extra compute past that point just costs more.",
  },
  {
    title: "How to read a cell",
    body: "Pick a Method and a System above. The left panel always explains the mechanism -- how that method would work on that system, even if nobody has ever run it. The right panel only shows real data where real data exists.",
  },
  {
    title: "Evidence tags matter",
    body: "Orange = we ran it ourselves, checkable against gold answers. Purple = published by someone else, not reproduced by us. Grey = an architectural argument, no chart attached. We never mix these up.",
  },
  {
    title: "Some cells are empty on purpose",
    body: "Most combinations show no results panel. Two of them -- BDH-CQ × Beam search and BDH-CQ × Budget forcing -- aren't just unstudied, they're architecturally blocked for the same underlying reason. Find them and see why.",
  },
];

let tutorialIndex = 0;

function renderTutorial() {
  const slide = TUTORIAL_SLIDES[tutorialIndex];
  $("#tutorial-title").textContent = slide.title;
  $("#tutorial-body").textContent = slide.body;
  $("#tutorial-index").textContent = `${tutorialIndex + 1} / ${TUTORIAL_SLIDES.length}`;
}

function setupTutorial() {
  renderTutorial();
  $("#tutorial-prev").addEventListener("click", () => {
    tutorialIndex = (tutorialIndex - 1 + TUTORIAL_SLIDES.length) % TUTORIAL_SLIDES.length;
    renderTutorial();
  });
  $("#tutorial-next").addEventListener("click", () => {
    tutorialIndex = (tutorialIndex + 1) % TUTORIAL_SLIDES.length;
    renderTutorial();
  });
  $("#tutorial-close").addEventListener("click", () => {
    $("#tutorial-card").hidden = true;
  });
}

async function loadData() {
  const contentRes = await fetch("data/content.json");
  CONTENT = await contentRes.json();

  try {
    const resultsRes = await fetch("data/results.json");
    if (resultsRes.ok) RESULTS = await resultsRes.json();
  } catch (e) {
    console.warn("results.json not available yet -- experiment cells will show a pending state.", e);
  }
}

function el(tag, opts = {}, children = []) {
  const node = document.createElement(tag);
  if (opts.className) node.className = opts.className;
  if (opts.text !== undefined) node.textContent = opts.text;
  if (opts.html !== undefined) node.innerHTML = opts.html;
  if (opts.attrs) for (const [k, v] of Object.entries(opts.attrs)) node.setAttribute(k, v);
  for (const c of children) if (c) node.appendChild(c);
  return node;
}

function evidenceTag(tier) {
  const meta = CONTENT.evidence_tiers[tier] || { label: tier };
  return el("span", { className: `evidence-tag ${tier}`, text: meta.label });
}

// ---------- explorer (mechanism + results panels) ----------

function populateDropdowns() {
  const methodSel = $("#method-select");
  const systemSel = $("#system-select");
  CONTENT.methods.forEach((m) => methodSel.appendChild(el("option", { text: m.label, attrs: { value: m.id } })));
  CONTENT.systems.forEach((s) => systemSel.appendChild(el("option", { text: s.label, attrs: { value: s.id } })));
  methodSel.value = "latent_compute";
  systemSel.value = "huginn";
}

function cellKeyFor(systemId, methodId) {
  return `${systemId}__${methodId}`;
}

// Real per-problem examples we actually captured, keyed to the two cells
// backed by our own sweep. Everywhere else the diagram stays illustrative
// and is labeled as such -- we never fake a live model response.

function listRealExamples(systemId, methodId) {
  if (methodId === "best_of_n" && systemId === "transformer") {
    const key = `${RESULTS_SYSTEM_MAP.transformer}__best_of_n__gsm8k`;
    const rows = RESULTS.per_problem[key] || [];
    const maxBudget = rows.reduce((m, r) => Math.max(m, r.budget), 0);
    const ids = [...new Set(rows.filter((r) => r.budget === maxBudget).map((r) => r.problem_id))];
    return ids.map((id) => ({ problem_id: id, question: RESULTS.questions?.[id]?.question }));
  }
  if (methodId === "latent_compute" && systemId === "huginn") {
    const seen = new Set();
    const out = [];
    ["gsm8k", "openbookqa"].forEach((t) => {
      const key = `${RESULTS_SYSTEM_MAP.huginn}__latent_compute__${t}`;
      (RESULTS.per_problem[key] || []).forEach((r) => {
        if (!seen.has(r.problem_id)) {
          seen.add(r.problem_id);
          out.push({ problem_id: r.problem_id, question: RESULTS.questions?.[r.problem_id]?.question });
        }
      });
    });
    return out;
  }
  if (methodId === "budget_forcing" && systemId === "transformer") {
    const key = `${RESULTS_SYSTEM_MAP.transformer}__budget_forcing__gsm8k`;
    const rows = RESULTS.per_problem[key] || [];
    const maxBudget = rows.reduce((m, r) => Math.max(m, r.budget), 0);
    const ids = [...new Set(rows.filter((r) => r.budget === maxBudget).map((r) => r.problem_id))];
    return ids.map((id) => ({ problem_id: id, question: RESULTS.questions?.[id]?.question }));
  }
  return [];
}

function getRealExampleDetail(systemId, methodId, problemId) {
  if (methodId === "best_of_n" && systemId === "transformer") {
    const key = `${RESULTS_SYSTEM_MAP.transformer}__best_of_n__gsm8k`;
    const rows = RESULTS.per_problem[key] || [];
    const maxBudget = rows.reduce((m, r) => Math.max(m, r.budget), 0);
    const row = rows.find((r) => r.problem_id === problemId && r.budget === maxBudget);
    if (!row) return null;
    return {
      problem_id: problemId,
      question: RESULTS.questions?.[problemId]?.question,
      gold: row.gold,
      majorityPrediction: row.prediction,
      correct: row.correct,
      samples: row.samples,
    };
  }
  if (methodId === "latent_compute" && systemId === "huginn") {
    for (const t of ["gsm8k", "openbookqa"]) {
      const key = `${RESULTS_SYSTEM_MAP.huginn}__latent_compute__${t}`;
      const row = (RESULTS.per_problem[key] || []).find((r) => r.problem_id === problemId);
      if (row) {
        return {
          problem_id: problemId,
          question: RESULTS.questions?.[problemId]?.question,
          gold: row.gold,
          prediction: row.prediction,
          correct: row.correct,
          rawOutput: row.raw_output,
          budget: row.budget,
        };
      }
    }
  }
  if (methodId === "budget_forcing" && systemId === "transformer") {
    const key = `${RESULTS_SYSTEM_MAP.transformer}__budget_forcing__gsm8k`;
    const rows = RESULTS.per_problem[key] || [];
    const maxBudget = rows.reduce((m, r) => Math.max(m, r.budget), 0);
    const row = rows.find((r) => r.problem_id === problemId && r.budget === maxBudget);
    if (!row) return null;
    return {
      problem_id: problemId,
      question: RESULTS.questions?.[problemId]?.question,
      gold: row.gold,
      prediction: row.prediction,
      correct: row.correct,
      forcedUsed: maxBudget,
      rawOutput: row.raw_output,
    };
  }
  return null;
}

const LIVE_BACKEND_URL = "http://localhost:8000";
let BACKEND_HEALTH = null;

async function checkBackendHealth() {
  try {
    const res = await fetch(`${LIVE_BACKEND_URL}/health`, { signal: AbortSignal.timeout(2500) });
    BACKEND_HEALTH = res.ok ? await res.json() : null;
  } catch (e) {
    BACKEND_HEALTH = null;
  }
}

function renderStage(cell, systemId, methodId) {
  const tagHost = $("#stage-tag");
  tagHost.innerHTML = "";
  tagHost.appendChild(evidenceTag(cell.evidence_tier));

  const interactHost = $("#stage-interact");
  interactHost.innerHTML = "";
  const diagramHost = $("#stage-diagram");
  diagramHost.innerHTML = "";
  if (_liveCleanup) {
    _liveCleanup();
    _liveCleanup = null;
  }

  if (isLiveCapable(systemId, methodId)) {
    // Primary interaction: real model, run live, streamed token-by-token.
    renderLiveControls(interactHost, diagramHost, systemId, methodId);
    renderMechanismDiagram(diagramHost, systemId, methodId, cell, null);

    // Fallback only: if the local backend isn't running, offer the offline
    // real-sweep replay instead of leaving the learner with nothing to try.
    if (!liveReady(systemId, methodId)) {
      const examples = listRealExamples(systemId, methodId);
      if (examples.length > 0) {
        const pickerWrap = el("div", { className: "question-picker" });
        pickerWrap.appendChild(el("label", { text: "Backend offline -- replay a question from our offline sweep instead" }));
        const select = el("select");
        examples.forEach((ex) => {
          const text = ex.question ? ex.question.slice(0, 70) + (ex.question.length > 70 ? "…" : "") : ex.problem_id;
          select.appendChild(el("option", { text, attrs: { value: ex.problem_id } }));
        });
        select.addEventListener("change", () => {
          renderMechanismDiagram(diagramHost, systemId, methodId, cell, getRealExampleDetail(systemId, methodId, select.value));
        });
        pickerWrap.appendChild(select);
        interactHost.appendChild(pickerWrap);
        renderMechanismDiagram(diagramHost, systemId, methodId, cell, getRealExampleDetail(systemId, methodId, examples[0].problem_id));
      }
    }
    return;
  }

  // No real model behind this cell (e.g. BDH-CQ has no public checkpoint) --
  // offer offline-sweep replay if we have it, otherwise the static
  // mechanism-only diagram. Never a live control here.
  const examples = listRealExamples(systemId, methodId);
  if (examples.length > 0) {
    const pickerWrap = el("div", { className: "question-picker" });
    pickerWrap.appendChild(el("label", { text: "Try a real question from our sweep" }));
    const select = el("select");
    examples.forEach((ex) => {
      const text = ex.question ? ex.question.slice(0, 70) + (ex.question.length > 70 ? "…" : "") : ex.problem_id;
      select.appendChild(el("option", { text, attrs: { value: ex.problem_id } }));
    });
    select.addEventListener("change", () => {
      renderMechanismDiagram(diagramHost, systemId, methodId, cell, getRealExampleDetail(systemId, methodId, select.value));
    });
    pickerWrap.appendChild(select);
    interactHost.appendChild(pickerWrap);
  }
  const initialExample = examples.length > 0 ? getRealExampleDetail(systemId, methodId, examples[0].problem_id) : null;
  renderMechanismDiagram(diagramHost, systemId, methodId, cell, initialExample);
}

function renderMechanism(cell, systemId, methodId) {
  const body = $("#mechanism-body");
  body.innerHTML = "";
  const m = cell.mechanism;

  if (cell.blocked) {
    body.appendChild(el("div", { className: "blocked-banner", text: "Architecturally blocked -- not just unstudied" }));
  }

  body.appendChild(el("p", { text: m.text }));

  if (m.pointer) body.appendChild(el("p", { html: `<em>${m.pointer}</em>` }));

  (m.equations || []).forEach((eq) => {
    const eqDiv = el("div", { className: "equation" });
    eqDiv.appendChild(document.createTextNode(eq.expr));
    if (eq.note) eqDiv.appendChild(el("span", { className: "note", text: eq.note }));
    body.appendChild(eqDiv);
  });

  (m.quotes || []).forEach((q) => {
    body.appendChild(el("div", { className: "quote", text: `"${q.text}" -- ${q.source}` }));
  });

  if (m.reproducibility_note) body.appendChild(el("p", { text: m.reproducibility_note }));
  if (m.gap) body.appendChild(el("p", { html: `<strong>The gap:</strong> ${m.gap}` }));

  (m.beats || []).forEach((beat, i) => {
    const beatDiv = el("div", { className: "beat" });
    beatDiv.appendChild(el("h4", { text: `${i + 1}. ${beat.heading}` }));
    beatDiv.appendChild(el("p", { text: beat.text }));
    body.appendChild(beatDiv);
  });
  if (m.closing) body.appendChild(el("p", { html: `<strong>${m.closing}</strong>` }));

  if (m.source) body.appendChild(el("p", { html: `<small>Source: ${m.source}</small>` }));
}

let _chartGradientSeq = 0;

function smoothPath(coords) {
  // coords: [[x,y], ...] -- smoothstep-style cubic bezier through points, no overshoot.
  let d = `M${coords[0][0].toFixed(1)},${coords[0][1].toFixed(1)}`;
  for (let i = 0; i < coords.length - 1; i++) {
    const [x0, y0] = coords[i];
    const [x1, y1] = coords[i + 1];
    const cpx = (x0 + x1) / 2;
    d += ` C${cpx.toFixed(1)},${y0.toFixed(1)} ${cpx.toFixed(1)},${y1.toFixed(1)} ${x1.toFixed(1)},${y1.toFixed(1)}`;
  }
  return d;
}

function makeLineChart(points, opts = {}) {
  // points: [{label, value}] categorical x-axis, evenly spaced
  const w = 420, h = 200, padL = 40, padR = 16, padT = 16, padB = 30;
  const innerW = w - padL - padR, innerH = h - padT - padB;
  const n = points.length;
  const xFor = (i) => padL + (n === 1 ? innerW / 2 : (i / (n - 1)) * innerW);
  const maxY = opts.maxY ?? 1;
  const yFor = (v) => padT + innerH - (v / maxY) * innerH;
  const gradId = `chartGrad${_chartGradientSeq++}`;

  const coords = points.map((p, i) => [xFor(i), yFor(p.value)]);
  const linePath = smoothPath(coords);
  const areaPath = `${linePath} L${coords[coords.length - 1][0].toFixed(1)},${(padT + innerH).toFixed(1)} L${coords[0][0].toFixed(1)},${(padT + innerH).toFixed(1)} Z`;

  let svg = `<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">`;
  svg += `<defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="var(--accent)" stop-opacity="0.35" />
    <stop offset="100%" stop-color="var(--accent)" stop-opacity="0" />
  </linearGradient></defs>`;
  // axes
  svg += `<line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT + innerH}" stroke="var(--border)" />`;
  svg += `<line x1="${padL}" y1="${padT + innerH}" x2="${padL + innerW}" y2="${padT + innerH}" stroke="var(--border)" />`;

  svg += `<path fill="url(#${gradId})" stroke="none" d="${areaPath}" />`;
  svg += `<path class="chart-line" d="${linePath}" />`;

  points.forEach((p, i) => {
    const isCurrent = opts.currentIndex === i;
    const pct = (p.value * 100).toFixed(1);
    svg += `<circle class="chart-point${isCurrent ? " current" : ""}" cx="${xFor(i).toFixed(1)}" cy="${yFor(p.value).toFixed(1)}" r="${isCurrent ? 5 : 3.5}"><title>budget ${p.label}: ${pct}%</title></circle>`;
    svg += `<text class="chart-axis-label" x="${xFor(i).toFixed(1)}" y="${h - 8}" text-anchor="middle">${p.label}</text>`;
  });
  // y ticks (0, 0.5, 1 scaled by maxY)
  [0, 0.5, 1].forEach((frac) => {
    const v = frac * maxY;
    svg += `<text class="chart-axis-label" x="${padL - 6}" y="${(yFor(v) + 3).toFixed(1)}" text-anchor="end">${Math.round(v * 100)}%</text>`;
  });
  svg += `</svg>`;
  return svg;
}

function renderOwnSweepResults(cell, systemId, methodId, container) {
  const mappedSystem = RESULTS_SYSTEM_MAP[systemId];
  const tasks = cell.results.tasks || [cell.results.task];
  let currentTask = tasks[0];

  const wrap = el("div");
  container.appendChild(el("p", { text: cell.results.note }));

  if (tasks.length > 1) {
    const toggle = el("div", { className: "task-toggle" });
    tasks.forEach((t) => {
      const btn = el("button", { text: t, attrs: { "data-task": t } });
      if (t === currentTask) btn.classList.add("active");
      btn.addEventListener("click", () => {
        currentTask = t;
        toggle.querySelectorAll("button").forEach((b) => b.classList.toggle("active", b.dataset.task === t));
        draw();
      });
      toggle.appendChild(btn);
    });
    wrap.appendChild(toggle);
  }

  const chartHost = el("div", { className: "chart-wrap" });
  const sliderHost = el("div", { className: "slider-block" });
  const detailHost = el("div", { className: "per-problem-detail" });
  wrap.appendChild(chartHost);
  wrap.appendChild(sliderHost);
  wrap.appendChild(detailHost);
  container.appendChild(wrap);

  function draw() {
    const curves = RESULTS.curves.filter(
      (c) => c.system === mappedSystem && c.method === methodId && c.task === currentTask
    );
    if (curves.length === 0) {
      chartHost.innerHTML = "";
      sliderHost.innerHTML = "";
      detailHost.innerHTML = "";
      chartHost.appendChild(
        el("div", {
          className: "no-data",
          text: "No aggregated data yet for this task -- run experiment/aggregate.py after the sweep completes.",
        })
      );
      return;
    }
    curves.sort((a, b) => a.budget - b.budget);
    const points = curves.map((c) => ({ label: c.budget, value: c.accuracy ?? 0 }));

    const perProblemKey = `${mappedSystem}__${methodId}__${currentTask}`;
    const perProblem = RESULTS.per_problem[perProblemKey] || [];
    const budgets = curves.map((c) => c.budget);

    let currentIdx = budgets.length - 1;

    function redraw() {
      chartHost.innerHTML = makeLineChart(points, { currentIndex: currentIdx });

      const budget = budgets[currentIdx];
      const rows = perProblem.filter((p) => p.budget === budget);
      detailHost.innerHTML = "";
      detailHost.appendChild(
        el("div", { html: `<strong>Budget = ${budget}</strong> &middot; ${curves[currentIdx].n_problems} problems &middot; accuracy ${(curves[currentIdx].accuracy * 100).toFixed(1)}%${curves[currentIdx].avg_latency_s ? ` &middot; avg latency ${curves[currentIdx].avg_latency_s.toFixed(1)}s` : ""}` })
      );
      rows.forEach((r) => {
        detailHost.appendChild(
          el("div", {
            className: "row",
            html: `<span>${r.problem_id}</span><span class="${r.correct ? "correct" : "incorrect"}">pred: ${r.prediction ?? "—"} / gold: ${r.gold} ${r.correct ? "✓" : "✗"}</span>`,
          })
        );
      });
    }

    sliderHost.innerHTML = "";
    const sliderLabel = el("div", { className: "slider-value" });
    sliderHost.appendChild(sliderLabel);
    const slider = el("input", {
      attrs: { type: "range", min: 0, max: budgets.length - 1, step: 1, value: currentIdx },
    });
    slider.addEventListener("input", (e) => {
      currentIdx = Number(e.target.value);
      sliderLabel.textContent = `Budget: ${budgets[currentIdx]}`;
      redraw();
    });
    sliderHost.appendChild(slider);
    sliderLabel.textContent = `Budget: ${budgets[currentIdx]}`;
    redraw();
  }

  draw();
}

function renderNoData(cell, container) {
  const box = el("div", { className: "no-data" });
  const reason = cell.mechanism.gap || cell.mechanism.text;
  box.appendChild(el("p", { html: `<strong>No results panel for this cell.</strong>` }));
  box.appendChild(el("p", { text: reason }));
  container.appendChild(box);

  const pub = cell.mechanism.published_reference;
  if (pub) {
    const pubBox = el("div", { className: "no-data" });
    pubBox.appendChild(evidenceTag("purple"));
    pubBox.appendChild(el("p", { text: pub.note }));
    pub.series.forEach((s) => {
      pubBox.appendChild(el("p", { html: `<strong>${s.task}</strong> (${s.metric})` }));
      const table = el("table", { className: "stat-table" });
      table.appendChild(el("tr", { html: s.points.map((p) => `<th>r=${p.r}</th>`).join("") }));
      table.appendChild(el("tr", { html: s.points.map((p) => `<td>${p.value.toFixed(2)}%</td>`).join("") }));
      pubBox.appendChild(table);
    });
    pubBox.appendChild(el("p", { html: `<small>Source: ${pub.source}</small>` }));
    container.appendChild(pubBox);
  }
}

function renderBdhCqTable(cell, container) {
  container.appendChild(el("p", { text: cell.results.note }));
  const table = el("table", { className: "stat-table" });
  table.appendChild(
    el("tr", { html: "<th>Effort</th><th>Pass@2</th><th>Cost reduction</th>" })
  );
  cell.results.table.forEach((row) => {
    table.appendChild(
      el("tr", {
        html: `<td>${row.effort}</td><td>${(row.pass_at_2 * 100).toFixed(1)}%</td><td>${(row.cost_reduction * 100).toFixed(0)}%</td>`,
      })
    );
  });
  container.appendChild(table);
  container.appendChild(el("div", { className: "chart-wrap", html: makeLineChart(
    cell.results.table.map((r) => ({ label: r.effort, value: r.pass_at_2 })),
    { maxY: 0.4 }
  ) }));
  container.appendChild(el("p", { html: `<small>${cell.results.also_cite}</small>` }));
  container.appendChild(el("p", { html: `<small><strong>${cell.results.label}</strong></small>` }));
}

function renderPublishedPending(cell, container) {
  container.appendChild(el("p", { text: cell.results.note }));
  if (cell.results.key_teaching_point) container.appendChild(el("p", { html: `<strong>Key teaching point:</strong> ${cell.results.key_teaching_point}` }));
  container.appendChild(
    el("div", {
      className: "no-data",
      text:
        cell.results.TODO ||
        "Chart pending exact source data. We do not fabricate curves -- see project notes.",
    })
  );
}

function renderResults(cell, systemId, methodId) {
  const tagHost = $("#results-tag");
  tagHost.innerHTML = "";
  const body = $("#results-body");
  body.innerHTML = "";

  if (!cell.has_results) {
    tagHost.appendChild(evidenceTag("grey"));
    renderNoData(cell, body);
    return;
  }

  tagHost.appendChild(evidenceTag(cell.evidence_tier));

  if (cell.results.data_ref) {
    renderOwnSweepResults(cell, systemId, methodId, body);
  } else if (cell.results.table) {
    renderBdhCqTable(cell, body);
  } else {
    renderPublishedPending(cell, body);
  }
}

function renderBdhStrip(methodId) {
  const strip = CONTENT.bdh_context_strip[methodId];
  const host = $("#bdh-strip");
  host.innerHTML = "";
  if (!strip) return;
  host.appendChild(el("p", { html: `<strong>BDH context:</strong> ${strip.text}` }));
  if (strip.equation) {
    host.appendChild(
      el("div", { className: "equation", html: `${strip.equation.expr}<span class="note">${strip.equation.source}</span>` })
    );
  }
}

function renderExplorerNow() {
  const methodId = $("#method-select").value;
  const systemId = $("#system-select").value;
  const cell = CONTENT.cells[cellKeyFor(systemId, methodId)];
  if (!cell) {
    console.error("Missing cell for", systemId, methodId);
    return;
  }
  renderStage(cell, systemId, methodId);
  renderMechanism(cell, systemId, methodId);
  renderResults(cell, systemId, methodId);
  renderBdhStrip(methodId);
}

function renderExplorer() {
  const bodies = [$("#stage-diagram"), $("#mechanism-body"), $("#results-body")];
  bodies.forEach((b) => (b.style.opacity = "0"));
  setTimeout(() => {
    renderExplorerNow();
    bodies.forEach((b) => (b.style.opacity = "1"));
  }, 140);
}

// ---------- failure moments ----------

function renderFailureMoment1() {
  const fm = CONTENT.failure_moments.failure_moment_1;
  const host = $("#failure-1-body");
  host.innerHTML = "";
  host.appendChild(evidenceTag(fm.available === false ? "grey" : fm.evidence_tier || "grey"));
  host.appendChild(el("p", { text: fm.description }));
  host.appendChild(el("p", { html: `<strong>Misconception corrected:</strong> "${fm.misconception_corrected}"` }));
  const btn = el("button", { text: "Open the Huginn × Latent compute panel above", attrs: { class: "jump-btn" } });
  btn.style.cssText = "background:var(--bg-panel);border:1px solid var(--border);color:var(--accent);border-radius:8px;padding:10px 16px;cursor:pointer;";
  btn.addEventListener("click", () => {
    $("#system-select").value = "huginn";
    $("#method-select").value = "latent_compute";
    renderExplorer();
    $("#explorer").scrollIntoView({ behavior: "smooth" });
  });
  host.appendChild(btn);
}

function renderFailureMoment2() {
  const fm = CONTENT.failure_moments.failure_moment_2;
  const host = $("#failure-2-body");
  host.innerHTML = "";
  const d = fm.data;
  const table = el("table", { className: "stat-table" });
  table.appendChild(el("tr", { html: "<th>Effort</th><th>Cost / task</th><th>Pass@2</th>" }));
  table.appendChild(el("tr", { html: `<td>MIN</td><td>$${d.min_effort.cost_per_task_usd}</td><td>${d.min_effort.pass_at_2}</td>` }));
  table.appendChild(el("tr", { html: `<td>STANDARD</td><td>$${d.standard_effort.cost_per_task_usd}</td><td>${d.standard_effort.pass_at_2}</td>` }));
  host.appendChild(table);
  host.appendChild(el("p", { html: `Difference: <strong>${d.difference_pp}pp</strong> for roughly <strong>${d.cost_multiplier}</strong> the cost.` }));

  const split = el("table", { className: "stat-table" });
  split.appendChild(el("tr", { html: "<th>Solved by both</th><th>STANDARD only</th><th>MIN only</th><th>Neither</th>" }));
  split.appendChild(el("tr", { html: `<td>${d.paired_split.both}</td><td>${d.paired_split.standard_only}</td><td>${d.paired_split.min_only}</td><td>${d.paired_split.neither}</td>` }));
  host.appendChild(split);

  host.appendChild(el("p", { html: `Two-sided exact McNemar <strong>p = ${d.mcnemar_p_two_sided_exact}</strong>` }));
  host.appendChild(el("div", { className: "quote", text: `"${fm.authors_quote}"` }));
  host.appendChild(el("p", { html: `<strong>Lesson:</strong> ${fm.lesson}` }));
}

// ---------- final challenge ----------

function renderFinalChallenge() {
  const fc = CONTENT.final_challenge;
  const host = $("#challenge-body");
  host.innerHTML = "";
  host.appendChild(el("p", { html: `<strong>${fc.prompt}</strong>` }));

  const choicesDiv = el("div", { className: "challenge-choices" });
  const reveal = el("div", { className: "challenge-reveal", attrs: { hidden: "" } });

  fc.choices.forEach((choice) => {
    const btn = el("button", { text: choice });
    btn.addEventListener("click", () => {
      choicesDiv.querySelectorAll("button").forEach((b) => b.classList.remove("selected"));
      btn.classList.add("selected");
      reveal.hidden = false;
      reveal.innerHTML = "";
      const cell = CONTENT.cells[fc.reveal_ref];
      renderMechanismInto(cell, reveal);
    });
    choicesDiv.appendChild(btn);
  });
  host.appendChild(choicesDiv);
  host.appendChild(reveal);

  host.appendChild(el("p", { html: `<strong>${fc.free_text_prompt}</strong>` }));
  host.appendChild(el("textarea", { className: "free-text", attrs: { placeholder: "Type your answer here..." } }));

  const check = fc.forced_choice_check;
  host.appendChild(el("p", { html: `<strong>${check.statement}</strong>` }));
  const tfDiv = el("div", { className: "challenge-choices" });
  const explanation = el("div", { className: "challenge-reveal", attrs: { hidden: "" }, text: check.explanation });
  ["True", "False"].forEach((label) => {
    const btn = el("button", { text: label });
    btn.addEventListener("click", () => {
      tfDiv.querySelectorAll("button").forEach((b) => b.classList.remove("selected"));
      const isCorrect = (label === "True") === check.correct_answer;
      btn.classList.add("selected");
      btn.style.borderColor = isCorrect ? "var(--green)" : "var(--red)";
      explanation.hidden = false;
    });
    tfDiv.appendChild(btn);
  });
  host.appendChild(tfDiv);
  host.appendChild(explanation);
}

function renderMechanismInto(cell, container) {
  const m = cell.mechanism;
  container.appendChild(el("p", { text: m.text }));
  (m.beats || []).forEach((beat, i) => {
    const beatDiv = el("div", { className: "beat" });
    beatDiv.appendChild(el("h4", { text: `${i + 1}. ${beat.heading}` }));
    beatDiv.appendChild(el("p", { text: beat.text }));
    container.appendChild(beatDiv);
  });
  if (m.closing) container.appendChild(el("p", { html: `<strong>${m.closing}</strong>` }));
}

