async function main() {
  await loadData();
  $("#central-claim").textContent = CONTENT.central_claim;
  renderHeroChart();
  populateDropdowns();
  renderExplorerNow();
  renderFailureMoment1();
  renderFailureMoment2();
  renderFinalChallenge();
  renderSources();
  setupTutorial();
  setupScrollReveal();

  $("#method-select").addEventListener("change", renderExplorer);
  $("#system-select").addEventListener("change", renderExplorer);

  // Don't block first paint on the live-backend health check -- render
  // immediately assuming it's offline, then re-render the current cell if
  // it turns out to be reachable so the live input activates.
  checkBackendHealth().then(() => {
    if (BACKEND_HEALTH && isLiveCapable($("#system-select").value, $("#method-select").value)) {
      renderExplorerNow();
    }
  });
}

main();
